		public MeasureTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Measure
		 * 
		 * @return Measure
		 */
		protected Measure generateNewEntity() {
			Measure entity = new Measure( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  new HashSet<>(),  new HashSet<>(),  AggregationType.values()[0] );
			
			return( entity );
		}

